#include <iostream>
#include <memory>

class MyClass {
public:
  MyClass() { std::cout << "MyClass constructed\n"; }
  ~MyClass() { std::cout << "MyClass destructed\n"; }
};

int main() {
  // Using unique_ptr
  std::unique_ptr<MyClass> uniquePtr(new MyClass); //or std::make_unique<MyClass>();

  // Using shared_ptr
  std::shared_ptr<MyClass> sharedPtr1 = std::make_shared<MyClass>();
  std::shared_ptr<MyClass> sharedPtr2 = sharedPtr1;

  // Using weak_ptr (observe sharedPtr1)
  std::weak_ptr<MyClass> weakPtr = sharedPtr1;
  if (auto sp = weakPtr.lock()) {  //Check if shared_ptr still exists
      std::cout << "Weak pointer still valid!\n";
  }
  return 0;
}
